  <text x="28" y="30" font-family="'Google Sans', 'Segoe UI', Roboto, sans-serif" font-weight="700" font-size="14" fill="{TEXT}">{USERNAME} // 30-Day Commit Activity ({sum(series)} contributions)</text>
